enum Command {
    Look,
    Inventory,
    Unknown(String),
}

fn parse(input: &str) -> Command {
    match input {
        "look" => Command::Look,
        "inventory" | "i" => Command::Inventory,
        _ => Command::Unknown(input.to_string()),
    }
}

fn describe(command: Command, inventory: &[&str]) -> String {
    match command {
        Command::Look => String::from("You see a dusty hall."),
        Command::Inventory => format!("You carry: {}", inventory.join(", ")),
        Command::Unknown(text) => format!("I don't understand '{text}'."),
    }
}

fn main() {
    let inventory = ["key", "lamp"];
    for input in ["look", "i", "dance"] {
        println!("{}", describe(parse(input), &inventory));
    }
}
